\title{The Euclidean Norm-Ratio Spectrum of Real Unimodular $2\times 2$ Matrices}
\author{Aristotle}
\date{June 25, 2026}

\begin{document}

\begin{abstract}
For a real $2\times2$ matrix $M$ and the Euclidean norm $k(v)=\sqrt{v_0^2+v_1^2}$ on
$\mathbb{R}^2$, define the \emph{ratio spectrum} of $M$ as the set of values $k(Mv)/k(v)$
over nonzero $v$. We prove that whenever $M$ is unimodular up to sign, i.e.
$(\det M)^2=1$, there exists a nonzero $v$ with $k(Mv)=k(v)$, so that $1$ belongs to the
ratio spectrum. Equivalently, the indefinite quadratic form
$Q(x,y)=(ax+by)^2+(cx+dy)^2-(x^2+y^2)$ associated with
$M=\left(\begin{smallmatrix}a&b\\c&d\end{smallmatrix}\right)$ has a nontrivial zero. The
proof reduces the geometric statement to a single discriminant inequality
$B^2-AC\ge 0$ with $A=a^2+c^2-1$, $B=ab+cd$, $C=b^2+d^2-1$, which is equivalent to the
Frobenius bound $a^2+b^2+c^2+d^2\ge 2|\det M|$. As a corollary, the degenerate interval
$[1,1]$---the collapse of $[\,1/|\det M|,|\det M|\,]$ at $|\det M|=1$---lies in the
closure of the ratio spectrum. All results have been formally verified.
\end{abstract}

\maketitle

\section{Introduction}

For a fixed real $2\times2$ matrix $M$ and nonzero $v\in\mathbb{R}^2$, the local stretch
factor is $k(Mv)/k(v)$, where $k$ is Euclidean length. As $v$ ranges over nonzero
vectors this quotient sweeps a closed interval bounded by the singular values of $M$; we
call the set of attained values the \emph{ratio spectrum} of $M$.

We ask which numbers are forced into the spectrum under a constraint on $M$. The cleanest
constraint is unimodularity, $|\det M|=1$, the condition that $M$ preserves area.
Unimodular matrices include rotations, shears, reflections of unit Jacobian, and (over
$\mathbb{Z}$) the modular group $\mathrm{SL}_2(\mathbb{Z})$.

\begin{theorem}[Unit ratio]\label{thm:main-intro}
If $M\in\mathbb{R}^{2\times2}$ satisfies $(\det M)^2=1$, then there exists a nonzero
$v\in\mathbb{R}^2$ with $k(Mv)=k(v)$.
\end{theorem}

Geometrically, every area-preserving linear map of the plane has a direction of unit
stretch. This is the unimodular cornerstone of a broader program: for a primitive integer
matrix $M$ with $\det M\neq 0$, the ratios $k(Mx)/k(x)$ over quadratic-irrational badly
approximable directions $x$ are conjecturally dense in
$[\,1/|\det M|,\ |\det M|\,]$. When $|\det M|=1$ that interval is $\{1\}$, and density
there is exactly Theorem~\ref{thm:main-intro}.

\section{Definitions}

Vectors are $v=(v_0,v_1)\in\mathbb{R}^2$ and
$M=\left(\begin{smallmatrix}a&b\\c&d\end{smallmatrix}\right)$ acts by
$Mv=(av_0+bv_1,\,cv_0+dv_1)$.

\begin{definition}[Euclidean norm]
$k(v)=\sqrt{v_0^2+v_1^2}$.
\end{definition}

\begin{definition}[Ratio spectrum]
$\ratioSpectrum(M)=\{\,r\in\mathbb{R}\mid \exists\,v\neq 0,\ r=k(Mv)/k(v)\,\}$.
\end{definition}

\begin{definition}[Unimodular up to sign]
$M$ is unimodular up to sign if $(\det M)^2=1$, i.e. $\det M=ad-bc\in\{+1,-1\}$.
\end{definition}

\begin{definition}[Associated quadratic form]
$Q_M(x,y)=(ax+by)^2+(cx+dy)^2-(x^2+y^2)=Ax^2+2Bxy+Cy^2$, with $A=a^2+c^2-1$, $B=ab+cd$,
$C=b^2+d^2-1$. Since $Q_M(x,y)=k(Mv)^2-k(v)^2$ for $v=(x,y)$, a nontrivial zero of $Q_M$
is the same as a nonzero $v$ with $k(Mv)=k(v)$.
\end{definition}

\section{Geometric picture: singular values}

Let $0\le\sigma_{\min}\le\sigma_{\max}$ be the singular values of $M$. The map
$v\mapsto k(Mv)/k(v)$ is continuous on the unit circle, so by the Intermediate Value
Theorem $\ratioSpectrum(M)=[\sigma_{\min},\sigma_{\max}]$. Moreover
$\sigma_{\min}\sigma_{\max}=|\det M|$. When $|\det M|=1$ this forces
$\sigma_{\min}\le 1\le\sigma_{\max}$, hence $1\in\ratioSpectrum(M)$. The certified proof
below is algebraic, making the witness explicit and avoiding analytic machinery.

\section{The algebraic core}

\begin{lemma}[\texttt{disc\_nonneg}]\label{lem:disc}
For all real $a,b,c,d$ with $(ad-bc)^2=1$,
\[
0\le (ab+cd)^2-(a^2+c^2-1)(b^2+d^2-1).
\]
\end{lemma}

\begin{proof}[Proof sketch]
By the Lagrange identity $(a^2+c^2)(b^2+d^2)=(ab+cd)^2+(ad-bc)^2$,
\[
B^2-AC=(a^2+b^2+c^2+d^2)-(ad-bc)^2-1=(a^2+b^2+c^2+d^2)-2 .
\]
Nonnegativity is the Frobenius--determinant bound, certified by the sums of squares
$a^2+b^2+c^2+d^2-2(ad-bc)=(a-d)^2+(b+c)^2\ge 0$ and
$a^2+b^2+c^2+d^2+2(ad-bc)=(a+d)^2+(b-c)^2\ge 0$, together with $(ad-bc)^2=1$.
\end{proof}

\begin{theorem}[\texttt{core\_exists}]\label{thm:core}
For all real $a,b,c,d$ with $(ad-bc)^2=1$, there exist $x,y\in\mathbb{R}$, not both zero,
with $(ax+by)^2+(cx+dy)^2=x^2+y^2$.
\end{theorem}

\begin{proof}[Proof sketch]
Let $A=a^2+c^2-1$, $B=ab+cd$, $C=b^2+d^2-1$.
If $A=0$, take $(x,y)=(1,0)$; the claim is $a^2+c^2=1$, i.e. $A=0$. If $A\neq0$, set
$s=\sqrt{B^2-AC}$ (real by Lemma~\ref{lem:disc}), $x=(-B+s)/A$, $y=1$. Then
\[
Ax^2+2Bx+C=\frac{(-B+s)^2+2B(-B+s)+AC}{A}=\frac{s^2-B^2+AC}{A}=0,
\]
so $Q_M(x,1)=0$ with $(x,1)\neq(0,0)$.
\end{proof}

\section{Main theorem and corollaries}

\begin{theorem}[\texttt{exists\_unit\_ratio}]\label{thm:main}
For every $M\in\mathbb{R}^{2\times2}$ with $(\det M)^2=1$ there is a nonzero $v$ with
$k(Mv)=k(v)$.
\end{theorem}

\begin{proof}[Proof sketch]
With $a=M_{00},b=M_{01},c=M_{10},d=M_{11}$ the hypothesis is $(ad-bc)^2=1$. By
Theorem~\ref{thm:core} pick $(x,y)\neq(0,0)$ with
$(ax+by)^2+(cx+dy)^2=x^2+y^2$ and set $v=(x,y)$. Then
$k(Mv)^2=(ax+by)^2+(cx+dy)^2=x^2+y^2=k(v)^2$, so $k(Mv)=k(v)$ and $v\neq 0$.
\end{proof}

\begin{corollary}[\texttt{one\_mem\_ratioSpectrum}]\label{cor:one}
If $(\det M)^2=1$, then $1\in\ratioSpectrum(M)$.
\end{corollary}

\begin{proof}[Proof sketch]
For the $v$ of Theorem~\ref{thm:main}, $k(v)>0$, so $k(Mv)/k(v)=1$.
\end{proof}

\begin{corollary}[\texttt{ratioSpectrum\_dense\_Icc}]\label{cor:dense}
If $(\det M)^2=1$, then $[1,1]\subseteq\overline{\ratioSpectrum(M)}$.
\end{corollary}

\begin{proof}[Proof sketch]
$[1,1]=\{1\}$, which lies in $\ratioSpectrum(M)$ by Corollary~\ref{cor:one}, hence in its
closure.
\end{proof}

The label $[1,1]$ is the collapse of $[\,1/|\det M|,|\det M|\,]$ at $|\det M|=1$;
Corollary~\ref{cor:dense} settles the unimodular case of the density program.

\section{Algorithm}

Given $a,b,c,d$ with $|ad-bc|=1$:
\begin{enumerate}
\item Compute $A=a^2+c^2-1$, $B=ab+cd$, $C=b^2+d^2-1$.
\item If $A=0$, return $(1,0)$.
\item Else $D=B^2-AC\ (\ge 0)$, $s=\sqrt D$, $x=(-B+s)/A$; return $(x,1)$.
\end{enumerate}
Correctness is Theorem~\ref{thm:core}; the sanity check is $D=a^2+b^2+c^2+d^2-2$ (the unimodular specialization of $D=\|M\|_F^2-(\det M)^2-1$). The
witness uses a single square root of a nonnegative real, so it is algebraic of degree
$\le 2$, a quadratic irrational over $\mathbb{Q}$.

\section{Discussion and future work}

Over $\mathbb{Z}$ the unimodular matrices form $\mathrm{GL}_2(\mathbb{Z})$, acting on the
upper half-plane by $z\mapsto(az+b)/(cz+d)$; the unit-ratio direction is the
eigendirection of $M^\top M$ with eigenvalue $1$. For
$M=\left(\begin{smallmatrix}2&1\\1&1\end{smallmatrix}\right)$ the recipe gives $A=4$,
$B=3$, $C=1$, $D=5$, and witness $((-3+\sqrt5)/4,\,1)$, built from $\sqrt5$.

Future directions: (1) discreteness of the metallic-ratio spectrum
$\mu_n=(n+\sqrt{n^2+4})/2$ with gaps $\mu_{n+1}-\mu_n\to1$; (2) the reciprocal spectrum
$1/\mu_n\to0$ accumulating only at $0$; (3) density in $[1,\infty)$ of two-letter
periodic continued fractions $[a;b,a,b,\dots]$, roots of $bx^2-abx-a=0$; (4) effective
single-direction density of $\{p+q\sqrt d\}$; (5) a Markov/Lagrange-style spectral gap
below the golden value $\mu_1=\varphi$.

\section{Conclusion}

Every real $2\times2$ matrix of determinant $\pm1$ fixes the Euclidean norm of some
nonzero vector; thus $1$ lies in its norm-ratio spectrum and $[1,1]$ lies in the closure
of that spectrum. The proof reduces the geometry to one discriminant inequality
equivalent to $a^2+b^2+c^2+d^2\ge 2|\det M|$ and yields the witness in closed form.

